#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_ballCount;
uniform float amzp_ballRadius;
uniform float amzp_spread;
uniform float amzp_zSpread;
layout(color) uniform half4 amzp_ballColor;
uniform float amzp_progress;
uniform float amzp_randomSize;
uniform float amzp_sizeVar;
uniform float amzp_randSeed;
uniform float amzp_posX;
uniform float amzp_posY;
uniform float amzp_posZ;
uniform float amzp_ior;
uniform float amzp_shininess;
uniform float amzp_reflectMix;
uniform float amzp_refractScale;
uniform float amzp_reflectScale;
uniform float amzp_fov;
uniform float amzp_lightX;
uniform float amzp_lightY;
uniform float amzp_lightZ;

    float2 getResolution(){
      float2 s = getTexSize((screen.zw/1.0));
      if (s.x <= 0.0 || s.y <= 0.0) s = float2(1920.0, 1080.0);
      return s;
    }
    float2 hash2(float n){ return fract(sin(float2(n, n + 1.0)) * 43758.5453); }
    float intersectSphere(float3 ro, float3 rd, float3 center, float radius){
      float3 oc = ro - center;
      float b = dot(oc, rd);
      float c = dot(oc, oc) - radius * radius;
      float h = b*b - c;
      if (h < 0.0) return -1.0;
      return -b - sqrt(h);
    }
    void amzRender(){
      float2 res = getResolution();
      float2 fragCoord = amzScreenNorm() * res;
      float2 uv = amzScreenNorm();
      float2 p = (fragCoord - 0.5 * res) / res.y;
      float3 ro = float3(0.0, 0.0, -2.0);
      float3 rd = normalize(float3(p, amzp_fov));
      float3 lightPos = normalize(float3(amzp_lightX, amzp_lightY, amzp_lightZ));
      float3 col = amzTexture(0, uv).rgb;
      float minT = 10000.0;
      float3 hitCenter = float3(0.0);
      int maxBalls = int(amzp_ballCount);
      float aspect = res.x / res.y;
      for(int i=0;i<400;i++){
        if (i >= maxBalls) break;
        float2 rnd = hash2(float(i) * 56.7 + amzp_randSeed);
        float t_anim = amzp_progress * 20.0 + (float(i) * 12.0);
        float3 center = float3(0.0);
        center.x = sin(t_anim + rnd.x * 6.2831853) * 0.8 * aspect * amzp_spread;
        center.y = cos(t_anim * 0.9 + rnd.y * 6.2831853) * 0.4 * amzp_spread;
        center.z = sin(t_anim * 0.5) * amzp_zSpread;
        center += float3(amzp_posX, amzp_posY, amzp_posZ);
        float rVar = 1.0;
        if ((amzp_randomSize>0.5)){ rVar = 1.0 + (rnd.x * 2.0 - 1.0) * amzp_sizeVar; }
        float rBall = clamp(amzp_ballRadius * rVar, 0.001, 10.0);
        float t = intersectSphere(ro, rd, center, rBall);
        if (t > 0.0 && t < minT){ minT = t; hitCenter = center; }
      }
      if (minT < 10000.0){
        float3 amzLocal_pos = ro + rd * minT;
        float3 normal = normalize(amzLocal_pos - hitCenter);
        float3 viewDir = -rd;
        float cosTheta = clamp(dot(normal, viewDir), 0.0, 1.0);
        float fresnel = pow(1.0 - cosTheta, 4.0);
        float reflStrength = (0.1 + 0.9 * fresnel) * amzp_reflectMix;
        float3 refrVec = refract(rd, normal, 1.0 / amzp_ior);
        float2 refrUV = uv + refrVec.xy * amzp_refractScale;
        float3 glassColor = amzTexture(0, refrUV).rgb;
        float3 absorb = amzp_ballColor.rgb * (0.5 + 0.5 * cosTheta);
        glassColor *= absorb * 1.5;
        float3 reflVec = reflect(rd, normal);
        float2 reflUV = uv + reflVec.xy * amzp_reflectScale;
        float3 reflColor = amzTexture(0, reflUV).rgb;
        float3 halfVec = normalize(lightPos + viewDir);
        float spec = pow(max(dot(normal, halfVec), 0.0), amzp_shininess);
        float3 sphereCol = mix(glassColor, reflColor, reflStrength);
        sphereCol += float3(1.0) * spec;
        sphereCol += float3(1.0, 0.2, 0.2) * fresnel * 0.3;
        col = sphereCol;
      }
      amzOutput = float4(col, 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

